import java.util.function.Consumer;

import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.junit.jupiter.api.Test;

class ExternalValueInitializerContextTest {

	private static final Value VALUE = SimpleValueFactory.getInstance().createIRI("urn:test:value");

	@Test
	void nestedInitializerScopesRestoreAfterFailureAndPreserveIdentity() {
		List<String> visits = new ArrayList<>();
		Consumer<Value> outer = value -> visits.add("outer");
		Consumer<Value> inner = value -> visits.add("inner");
		assertNull(QueryExecutionContext.getExternalValueInitializer());
		try (QueryExecutionContext.Activation ignored = QueryExecutionContext.activateExternalValueInitializer(outer)) {
			assertSame(VALUE, QueryExecutionContext.initializeExternalValue(VALUE));
			assertThrows(IllegalStateException.class, () -> {
				try (QueryExecutionContext.Activation nested = QueryExecutionContext
						.activateExternalValueInitializer(inner)) {
					QueryExecutionContext.initializeExternalValues(null, VALUE);
					throw new IllegalStateException("callback failed");
				}
			});
			MapBindingSet bindings = new MapBindingSet();
			bindings.addBinding("v", VALUE);
			assertSame(bindings, QueryExecutionContext.initializeExternalBindings(bindings));
			assertNull(QueryExecutionContext.initializeExternalValue(null));
		}
		assertEquals(List.of("outer", "inner", "outer"), visits);
		assertNull(QueryExecutionContext.getExternalValueInitializer());
	}

	@Test
	void capturedInitializerWorksOnWorkerAndRestoresPriorInitializerAfterFailure() throws Exception {
		List<String> visits = new ArrayList<>();
		Consumer<Value> captured = value -> visits.add("captured");
		Consumer<Value> prior = value -> visits.add("prior");
		QueryExecutionContext.ReplayContext replay;
		try (QueryExecutionContext.Activation ignored = QueryExecutionContext
				.activateExternalValueInitializer(captured)) {
			replay = QueryExecutionContext.captureReplayContext();
		}
		ExecutorService executor = Executors.newSingleThreadExecutor();
		try {
			executor.submit(() -> {
				try (QueryExecutionContext.Activation ignored = QueryExecutionContext
						.activateExternalValueInitializer(prior)) {
					assertThrows(IllegalStateException.class, () -> replay.run(() -> {
						QueryExecutionContext.initializeExternalValue(VALUE);
						throw new IllegalStateException("worker callback failed");
					}));
					assertSame(prior, QueryExecutionContext.getExternalValueInitializer());
					QueryExecutionContext.initializeExternalValue(VALUE);
				}
				assertNull(QueryExecutionContext.getExternalValueInitializer());
			}).get(5, TimeUnit.SECONDS);
		} finally {
			executor.shutdownNow();
		}
		assertEquals(List.of("captured", "prior"), visits);
		assertNull(QueryExecutionContext.captureReplayContext());
	}
}
